/bin/bash -lc "python - <<'PY'
import sim, mujoco, numpy as np
s = sim.Sim()
for name in ['hand','left_finger','right_finger','cup','bin','table']:
    try:
        bid = mujoco.mj_name2id(s.model, mujoco.mjtObj.mjOBJ_BODY, name)
        print(name, 'xpos', s.data.xpos[bid], 'xmat', s.data.xmat[bid].reshape(3,3))
    except Exception as e:
        print(name, e)
PY"

